parameters.jsCode:
const items = $input.all();
const inputs = $('Store Inputs').first().json;

// Prefer AI-extracted terms over raw client_service
let aiOutput = {};
try { aiOutput = $('AI - Parse Target Description').first().json.output || {}; } catch(e) {}
const aiTerms = (aiOutput.search_terms || '').split(',').map(s => s.trim()).filter(Boolean);
const aiLocation = aiOutput.search_location || '';

const service = aiTerms[0] || inputs.client_service || inputs.industry || 'service';
const location = aiLocation || inputs.location || '';
const industry = inputs.industry || '';

const signals = [];

for (const item of items) {
  const data = item.json;

  // Reddit posts
  if (data.data && data.data.children) {
    for (const post of data.data.children) {
      const p = post.data;
      if (p && p.title) signals.push({
        source: 'Reddit',
        text: (p.title + ' ' + (p.selftext || '')).substring(0, 500),
        url: p.permalink ? 'https://reddit.com' + p.permalink : '',
        upvotes: p.score || 0,
        author: p.author || null,
        service, location, industry
      });
    }
  }

  // Yelp reviews
  if (data.name && data.reviews && Array.isArray(data.reviews)) {
    for (const review of data.reviews) {
      if (review.text) signals.push({
        source: 'Yelp',
        text: review.text.substring(0, 500),
        url: data.url || '',
        upvotes: 0,
        author: review.user?.name || null,
        service, location, industry
      });
    }
  }

  // Twitter
  if (data.full_text || data.text) {
    signals.push({
      source: 'Twitter',
      text: (data.full_text || data.text || '').substring(0, 500),
      url: data.url || '',
      upvotes: (data.favorite_count || 0) + (data.retweet_count || 0),
      author: data.user?.screen_name || null,
      service, location, industry
    });
  }

  // YouTube comments
  if (data.text && data.videoUrl) signals.push({
    source: 'YouTube',
    text: data.text.substring(0, 500),
    url: data.videoUrl || '',
    upvotes: data.likes || 0,
    author: data.authorText || null,
    service, location, industry
  });

  // YouTube video titles
  if (data.title && data.channelName && !data.text) signals.push({
    source: 'YouTube',
    text: (data.title + ' ' + (data.description || '')).substring(0, 400),
    url: data.url || '',
    upvotes: data.viewCount || 0,
    author: data.channelName || null,
    service, location, industry
  });
}

if (signals.length === 0) {
  return [{ json: { source: 'No signals', text: 'No signals found for ' + service + ' in ' + location, url: '', upvotes: 0, author: null, service, location, industry, __empty: true } }];
}

return signals.map(s => ({ json: s }));

